${finopsUsage:raw}
agentUsage
| summarize ['Calls'] = count(), ['Input tokens'] = sum(coalesce(inputTokens, long(0))),
    ['Output tokens'] = sum(coalesce(outputTokens, long(0))),
    credits = sum(aiCredits), creditCalls = countif(isnotnull(aiCredits)),
    azure = sum(azureCost), azureCalls = countif(isnotnull(azureCost))
    by ['Agent'] = agentLabel, ['Provider'] = providerLabel, ['Model'] = model, ['Cost basis'] = costingState
// A sum over nothing but nulls is zero in KQL, which would read as free, so an absent
// cost is only shown when at least one call actually carried one.
| extend ['AI credits'] = iff(creditCalls > 0, credits, real(null)),
    ['Estimated cost'] = case(creditCalls > 0, credits * todouble('${creditRate}'),
        azureCalls > 0, azure, real(null)),
    ['Currency'] = case(creditCalls > 0, 'USD', azureCalls > 0, tostring(priceCurrency), '')
| project-away credits, creditCalls, azure, azureCalls
| order by ['Input tokens'] desc

